1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.server.http.ServerHttpConnection;
4	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
5	import org.springframework.samples.petclinic.rest.escalation.IdempotentReplayException;
6	
7	/**
8	 * First step of create-owner: when the request repeats an already-seen {@code Idempotency-Key},
9	 * escalate {@link IdempotentReplayException} so the original owner is replayed with 200; otherwise
10	 * fall through to the normal create pipeline.
11	 */
12	public class CheckIdempotencyKey {
13	
14	    public void service(ServerHttpConnection connection, IdempotencyStore store)
15	            throws IdempotentReplayException {
16	        String key = IdempotencyKey.read(connection);
17	        if (key == null) {
18	            return;
19	        }
20	        OwnerDto existing = store.find(key);
21	        if (existing != null) {
22	            throw new IdempotentReplayException(existing);
23	        }
24	    }
25	}
