3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DailyOwnerLimitException;
7	
8	/**
9	 * Rejects a create request once {@value #DAILY_LIMIT} or more owners have already been
10	 * created today (by registrationDate). At or above the limit rejects 429.
11	 */
12	public class RequireDailyLimit {
13	
14	    private static final int DAILY_LIMIT = 100;
15	
16	    public void service(OwnerRepository ownerRepository) throws DailyOwnerLimitException {
17	        LocalDate today = BusinessDay.roll(LocalDate.now());
18	        long count = ownerRepository.findAll().stream()
19	                .filter(owner -> today.equals(owner.getRegistrationDate()))
20	                .count();
21	        if (count >= DAILY_LIMIT) {
22	            throw new DailyOwnerLimitException(count);
23	        }
24	    }
25	}
