1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * Rejects a create request that is missing or blank in any required owner field, before
13	 * {@link BuildOwner} runs. Publishes the body so the single {@code @RequestBody} binding lives here.
14	 */
15	public class RequireOwnerFields {
16	
17	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
18	            throws MissingOwnerFieldsException {
19	        request.setAddress(effectiveAddress(request));
20	        List<String> missing = new ArrayList<>();
21	        require("firstName", request.getFirstName(), missing);
22	        require("lastName", request.getLastName(), missing);
23	        require("address", request.getAddress(), missing);
24	        require("city", request.getCity(), missing);
25	        require("telephone", request.getTelephone(), missing);
26	        if (!missing.isEmpty()) {
27	            throw new MissingOwnerFieldsException(missing);
28	        }
29	        validated.set(request);
30	    }
31	
32	    /**
33	     * The address to store: the composed normalized structured address (normalized addressLine1,
34	     * plus a single space and the normalized addressLine2 when present) when a non-blank addressLine1
35	     * is supplied, otherwise the normalized flat {@code address} (backward compatible).
36	     */
37	    private static String effectiveAddress(OwnerFieldsDto request) {
38	        String line1 = AddressNormalizer.normalize(request.getAddressLine1());
39	        if (line1.isEmpty()) {
40	            return AddressNormalizer.normalize(request.getAddress());
41	        }
42	        String line2 = AddressNormalizer.normalize(request.getAddressLine2());
43	        return line2.isEmpty() ? line1 : line1 + " " + line2;
44	    }
45	
46	    private static void require(String name, String value, List<String> missing) {
47	        if (value == null || value.isBlank()) {
48	            missing.add(name);
49	        }
50	    }
51	}
