1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
8	
9	/**
10	 * Rejects a create request whose optional {@code postcode} is present but invalid: it
11	 * must be four digits and, for a city with a known region, within that region's range
12	 * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any
13	 * four-digit value. Absent postcode is accepted (validated only when present).
14	 */
15	public class RequireValidPostcode {
16	
17	    private static final Map<String, int[]> REGION_RANGE = Map.of(
18	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
19	
20	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
21	        String postcode = request.getPostcode();
22	        if (postcode == null) {
23	            return;
24	        }
25	        if (!postcode.matches("[0-9]{4}")) {
26	            throw new InvalidPostcodeException(postcode);
27	        }
28	        int[] range = REGION_RANGE.get(CityLocality.of(request.getCity()));
29	        int value = Integer.parseInt(postcode);
30	        if (range != null && (value < range[0] || value > range[1])) {
31	            throw new InvalidPostcodeException(postcode);
32	        }
33	    }
34	}
