1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.List;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
8	
9	/**
10	 * Rewrites the create request's telephone into E.164 form, storing it in place. Spaces, dashes and
11	 * brackets are stripped; a leading '+' and country code are kept, otherwise country code '+61' is
12	 * assumed and a single leading '0' is dropped from the national digits. Runs before {@link BuildOwner},
13	 * so the entity and the response both carry the E.164 form; anything that cannot yield 8 to 15 digits
14	 * after the '+' rejects with 400.
15	 */
16	public class NormalizeOwnerTelephone {
17	
18	    public void service(@Val OwnerFieldsDto request) throws MissingOwnerFieldsException {
19	        String cleaned = request.getTelephone().replaceAll("[\\s()\\-]", "");
20	        String e164;
21	        if (cleaned.startsWith("+")) {
22	            e164 = cleaned;
23	        }
24	        else {
25	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
26	            e164 = "+61" + national;
27	        }
28	        if (!e164.substring(1).matches("\\d{8,15}")) {
29	            throw new MissingOwnerFieldsException(List.of("telephone"));
30	        }
31	        request.setTelephone(e164);
32	    }
33	}
