3	import java.util.List;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
8	
9	/**
10	 * Checks the E.164 telephone's national-number length against its country code: '+61' requires 9
11	 * national digits and '+1' requires 10. Runs after {@link NormalizeOwnerTelephone}, so the value is
12	 * already in E.164 form; a wrong national length for the country rejects with 400.
13	 */
14	public class ValidateTelephoneCountryLength {
15	
16	    public void service(@Val OwnerFieldsDto request) throws MissingOwnerFieldsException {
17	        String telephone = request.getTelephone();
18	        check(telephone, "+61", 9);
19	        check(telephone, "+1", 10);
20	    }
21	
22	    private static void check(String telephone, String countryCode, int nationalDigits)
23	            throws MissingOwnerFieldsException {
24	        if (telephone.startsWith(countryCode) && telephone.length() - countryCode.length() != nationalDigits) {
25	            throw new MissingOwnerFieldsException(List.of("telephone"));
26	        }
27	    }
28	}
