1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.List;
4	import java.util.Set;
5	import java.util.regex.Pattern;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
10	
11	/**
12	 * Optional email: when absent the request is untouched; when present it must be a syntactically
13	 * valid address, stored lower-cased in place so the entity and the response both carry it. An
14	 * invalid address rejects with 400 via {@link MissingOwnerFieldsException}.
15	 */
16	public class NormalizeOwnerEmail {
17	
18	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
19	
20	    private static final Set<String> DISPOSABLE_DOMAINS = Set.of(
21	            "mailinator.com", "tempmail.com", "guerrillamail.com");
22	
23	    public void service(@Val OwnerFieldsDto request) throws MissingOwnerFieldsException {
24	        String email = request.getEmail();
25	        if (email == null) {
26	            return;
27	        }
28	        if (!EMAIL.matcher(email).matches()) {
29	            throw new MissingOwnerFieldsException(List.of("email"));
30	        }
31	        String normalized = email.toLowerCase();
32	        if (DISPOSABLE_DOMAINS.contains(normalized.substring(normalized.indexOf('@') + 1))) {
33	            throw new MissingOwnerFieldsException(List.of("email"));
34	        }
35	        request.setEmail(normalized);
36	    }
37	}
