3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerTelephoneException;
8	
9	/**
10	 * Consolidated duplicate guard: rejects a create request whose WHOLE {@code identityKey} equals an
11	 * existing owner's (see {@link OwnerIdentity}). Telephone is part of the key, so household members
12	 * with different telephones have different keys and are both allowed; only an exact full-key match is
13	 * a duplicate. A collision necessarily shares the telephone, so it reports 409 via
14	 * {@link DuplicateOwnerTelephoneException}.
15	 */
16	public class RequireUniqueIdentity {
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws DuplicateOwnerTelephoneException {
20	        String key = OwnerIdentity.key(request.getTelephone(), request.getEmail(), request.getLastName());
21	        for (Owner owner : ownerRepository.findAll()) {
22	            if (owner.isDeleted()) {
23	                continue;
24	            }
25	            if (key.equals(OwnerIdentity.key(owner.getTelephone(), owner.getEmail(), owner.getLastName()))) {
26	                throw new DuplicateOwnerTelephoneException(request.getTelephone());
27	            }
28	        }
29	    }
30	}
