1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.HexFormat;
7	import java.util.Set;
8	import java.util.stream.Collectors;
9	
10	import net.officefloor.plugin.variable.Val;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.repository.OwnerRepository;
13	
14	/**
15	 * Assigns the owner's memberId as {@code <REGION><FY><HASH8><CHK>}: REGION is the region code
16	 * derived from the postcode (see {@link CityLocality}), FY is the two-digit fiscal year of the
17	 * registrationDate (see {@link FiscalYear}), HASH8 is the first eight upper-case hex characters
18	 * of SHA-256 over the normalized telephone followed by the last name, and CHK is a single Luhn
19	 * check digit over the digits of {@code <REGION><FY><HASH8>} (see {@link CheckDigit}). On a
20	 * collision with an existing owner's memberId, {@code -<n>} (smallest n of 2 or more) is appended
21	 * so distinct owners always get distinct ids.
22	 */
23	public class AssignCustomerCode {
24	
25	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
26	        String region = "V2" + CityLocality.of(owner.getCity(), owner.getPostcode());
27	        String prefix = region + String.format("%02d", FiscalYear.shortYear(owner.getRegistrationDate()))
28	                + hash8(owner.getTelephone() + owner.getLastName());
29	        String base = prefix + CheckDigit.of(prefix);
30	        Set<String> taken = ownerRepository.findAll().stream()
31	                .map(Owner::getMemberId).collect(Collectors.toSet());
32	        String memberId = base;
33	        for (int n = 2; taken.contains(memberId); n++) {
34	            memberId = base + "-" + n;
35	        }
36	        owner.setMemberId(memberId);
37	    }
38	
39	    private static String hash8(String value) {
40	        try {
41	            byte[] digest = MessageDigest.getInstance("SHA-256")
42	                    .digest(value.getBytes(StandardCharsets.UTF_8));
43	            return HexFormat.of().formatHex(digest).substring(0, 8).toUpperCase();
44	        }
45	        catch (NoSuchAlgorithmException ex) {
46	            throw new IllegalStateException(ex);
47	        }
48	    }
49	}
