7	/**
8	 * Records how many owners belong to this owner's household (same computed {@code householdId} —
9	 * last name and postcode, see {@link HouseholdId}) after this create, i.e. the existing members
10	 * plus the new owner. Drives the 'GOLD' membership tier.
11	 */
12	public class CountHousehold {
13	
14	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
15	        String household = HouseholdId.of(owner.getLastName(), owner.getPostcode());
16	        long existing = ownerRepository.findAll().stream()
17	                .filter(other -> household.equals(HouseholdId.of(other.getLastName(), other.getPostcode())))
18	                .count();
19	        owner.setHouseholdCount((int) existing + 1);
20	    }
