1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Soft-match flag: a create that has already cleared the hard identity guard but whose
10	 * {@code identityKey} still differs from an existing owner sharing its {@code soundex(lastName)}
11	 * and postcode is recorded as a possible duplicate. Sets {@code possibleDuplicate} true and
12	 * {@code possibleDuplicateOf} to that owner's id, otherwise false. A declared household member
13	 * ({@code sharesHousehold} true) is never a suspected duplicate.
14	 */
15	public class FlagPossibleDuplicate {
16	
17	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
18	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
19	            owner.setPossibleDuplicate(false);
20	            return;
21	        }
22	        String soundex = Soundex.of(owner.getLastName());
23	        String postcode = normalize(owner.getPostcode());
24	        String key = OwnerIdentity.key(owner.getTelephone(), owner.getEmail(), owner.getLastName());
25	        for (Owner other : ownerRepository.findAll()) {
26	            if (!postcode.isEmpty() && soundex.equals(Soundex.of(other.getLastName()))
27	                    && postcode.equals(normalize(other.getPostcode()))
28	                    && !key.equals(OwnerIdentity.key(other.getTelephone(), other.getEmail(), other.getLastName()))) {
29	                owner.setPossibleDuplicate(true);
30	                owner.setPossibleDuplicateOf(other.getId());
31	                return;
32	            }
33	        }
34	        owner.setPossibleDuplicate(false);
35	    }
36	
37	    private static String normalize(String value) {
38	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
39	    }
40	}
