1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.mapper.OwnerMapper;
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Caps the new owner's membershipLevel at one above the highest membershipLevel among the existing
10	 * members of their household (same computed {@code householdId}, see {@link HouseholdId}). With no
11	 * existing household member the natural level stands, i.e. no cap applies.
12	 */
13	public class CapMembershipLevel {
14	
15	    public void service(@Val Owner owner, OwnerRepository ownerRepository, OwnerMapper ownerMapper) {
16	        String household = HouseholdId.of(owner.getLastName(), owner.getPostcode());
17	        int highest = ownerRepository.findAll().stream()
18	                .filter(other -> household.equals(HouseholdId.of(other.getLastName(), other.getPostcode())))
19	                .mapToInt(ownerMapper::membershipLevel)
20	                .max().orElse(-1);
21	        if (highest < 0) {
22	            return;
23	        }
24	        int natural = MembershipPoints.level(MembershipPoints.of(owner));
25	        owner.setMembershipLevel(Math.min(natural, highest + 1));
26	    }
27	}
