1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.net.URI;
4	import java.time.LocalDate;
5	import java.util.concurrent.atomic.AtomicLong;
6	
7	import net.officefloor.plugin.variable.Val;
8	import net.officefloor.web.ObjectResponse;
9	import org.springframework.http.ResponseEntity;
10	import org.springframework.samples.petclinic.mapper.OwnerMapper;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.repository.OwnerRepository;
13	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
14	
15	public class RespondWithOwnerCreated {
16	
17	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
18	
19	    private static final org.slf4j.Logger NOTIFY = org.slf4j.LoggerFactory.getLogger("NOTIFY");
20	
21	    private static final AtomicLong SEQ = new AtomicLong();
22	
23	    public void service(@Val Owner owner, OwnerMapper ownerMapper, OwnerRepository ownerRepository,
24	            ObjectResponse<ResponseEntity<OwnerDto>> response) {
25	        OwnerDto dto = ownerMapper.toOwnerDto(owner);
26	        LocalDate today = BusinessDay.roll(LocalDate.now());
27	        long createdToday = ownerRepository.findAll().stream()
28	                .filter(other -> today.equals(other.getRegistrationDate())).count();
29	        dto.setBulkSignupWarning(createdToday > 80);
30	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
31	                owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), dto.getMembershipLevel());
32	        AUDIT.info("{\"seq\":{},\"schemaVersion\":2,\"ownerId\":{},\"memberId\":\"{}\",\"membershipLevel\":{},\"ownerSegment\":\"{}\",\"event\":\"OWNER_CREATED\"}",
33	                SEQ.incrementAndGet(), owner.getId(), owner.getMemberId(), dto.getMembershipLevel(), dto.getOwnerSegment());
34	        NOTIFY.info("welcome ownerId={} memberId={}", owner.getId(), owner.getMemberId());
35	        response.send(ResponseEntity.created(URI.create("/api/owners/" + owner.getId())).body(dto));
36	    }
37	}
