1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.server.http.HttpHeader;
4	import net.officefloor.server.http.ServerHttpConnection;
5	
6	/**
7	 * Reads the optional {@code Idempotency-Key} request header shared by the create-owner
8	 * pipeline's idempotency steps.
9	 */
10	public final class IdempotencyKey {
11	
12	    static final String HEADER = "Idempotency-Key";
13	
14	    private IdempotencyKey() {
15	    }
