3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	import java.util.Set;
6	
7	/**
8	 * Business-day calendar helper. A registration date must fall on a business day, so a
9	 * Saturday, Sunday or public holiday rolls forward to the next business day.
10	 */
11	public final class BusinessDay {
12	
13	    /** Fixed public holidays the business-day roll skips. */
14	    private static final Set<LocalDate> HOLIDAYS = Set.of(
15	            LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
16	            LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
17	
18	    private BusinessDay() {
19	    }
20	
21	    private static boolean isBusinessDay(LocalDate date) {
22	        return date.getDayOfWeek() != DayOfWeek.SATURDAY && date.getDayOfWeek() != DayOfWeek.SUNDAY
23	                && !HOLIDAYS.contains(date);
24	    }
25	
26	    /** The given date, or the next business day when it falls on a weekend or holiday. */
27	    public static LocalDate roll(LocalDate date) {
28	        while (!isBusinessDay(date)) {
29	            date = date.plusDays(1);
30	        }
31	        return date;
32	    }
33	}
