3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.HexFormat;
7	
8	/**
9	 * Derives an owner's {@code identityKey}, the single value all duplicate detection is based on:
10	 * the SHA-256 hex digest of {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}.
11	 * Two owners are duplicates only when their whole keys are equal.
12	 *
13	 * <p>Telephone is part of the key, so two owners sharing a last name and postcode but carrying
14	 * different telephones have different keys and are not hard duplicates: they are allowed and merely
15	 * flagged as a possible (soft) duplicate elsewhere.
16	 */
17	public final class OwnerIdentity {
18	
19	    private OwnerIdentity() {
20	    }
21	
22	    public static String key(String telephone, String email, String lastName) {
23	        String tel = telephone == null ? "" : telephone;
24	        String mail = email == null ? "" : email.toLowerCase();
25	        String raw = "V2|" + tel + "|" + mail + "|" + Soundex.of(lastName);
26	        try {
27	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8));
28	            return HexFormat.of().formatHex(digest);
29	        }
30	        catch (NoSuchAlgorithmException ex) {
31	            throw new IllegalStateException(ex);
32	        }
33	    }
34	}
