5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Membership scoring. Points start at 0 and add: +2 when an email is present, +1 when the owner
9	 * has no namesakes (namesakeCount 0), +2 for a household of 3 or more, +3 for tenure over 365 days.
10	 * Points map to a level: 1 (0-1 points), 2 (2-3), 3 (4-5), 4 (6 or more).
11	 */
12	public final class MembershipPoints {
13	
14	    private MembershipPoints() {
15	    }
16	
17	    public static int of(Owner owner) {
18	        int points = 0;
19	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
20	            points += 2;
21	        }
22	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
23	            points += 1;
24	        }
25	        if (owner.getHouseholdCount() != null && owner.getHouseholdCount() >= 3) {
26	            points += 2;
27	        }
28	        LocalDate registration = owner.getRegistrationDate();
29	        if (registration != null && FiscalYear.elapsedTo(registration, LocalDate.now()) >= 1) {
30	            points += 3;
31	        }
32	        return points;
33	    }
34	
35	    public static int level(int points) {
36	        if (points <= 1) {
37	            return 1;
38	        }
39	        if (points <= 3) {
40	            return 2;
41	        }
42	        if (points <= 5) {
43	            return 3;
44	        }
45	        return 4;
46	    }
47	}
