5	/**
6	 * Canonical form of an owner address, applied on create and used for every address comparison
7	 * (household duplicate detection and the shared household id). Whitespace is trimmed and collapsed,
8	 * the text is upper-cased and common street-type abbreviations are expanded (ST->STREET, RD->ROAD,
9	 * AVE->AVENUE). A null or all-whitespace address normalizes to {@code ""}.
10	 */
11	public final class AddressNormalizer {
12	
13	    private static final Map<String, String> ABBREVIATIONS =
14	            Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
15	
16	    private AddressNormalizer() {
17	    }
18	
19	    public static String normalize(String address) {
20	        if (address == null || address.isBlank()) {
21	            return "";
22	        }
23	        StringBuilder sb = new StringBuilder();
24	        for (String word : address.trim().toUpperCase().split("\\s+")) {
25	            if (sb.length() > 0) {
26	                sb.append(' ');
27	            }
28	            sb.append(ABBREVIATIONS.getOrDefault(word, word));
29	        }
30	        return sb.toString();
31	    }
